/bin/bash -lc "python - <<'PY'
import os, requests, json
url=os.environ['GALAXY_URL'].rstrip('/')
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
for q in ['scanpy', 'anndata']:
    r=requests.get(url+'/api/tools', params={'q':q, 'in_panel':'False'}, headers={'x-api-key':key}, timeout=30)
    data=r.json()
    print('\\n', q, len(data))
    for item in data:
        if isinstance(item, str):
            tid=item
            meta=requests.get(url+'/api/tools/'+requests.utils.quote(tid, safe=''), headers={'x-api-key':key}, timeout=30)
            if meta.status_code==200:
                j=meta.json(); print(tid, '|', j.get('name'))
            else:
                print(tid)
        else:
            print(item.get('id'), item.get('name'))
PY"

